// Vem do Inbox: {conv:'cw_123', texto, autor, arquivo(base64), nomeArquivo, mime, tipo}
// O arquivo sai daqui como BINARIO — e assim que o Chatwoot o aceita
// (multipart), e e assim que ele chega ao cliente no WhatsApp.
const b = $json.body || $json;
const conv = String(b.conv || '');
const num = conv.replace(/^cw_/, '');
const base64 = String(b.arquivo || '');
if (!/^\d+$/.test(num) || !base64) return [];

const nome = String(b.nomeArquivo || 'arquivo').slice(0, 120);
const mime = String(b.mime || 'application/octet-stream');
const quem = String(b.autor || '').trim() || '?';
const texto = String(b.texto || '').trim().slice(0, 4000);
const ts = Date.now();

// O cliente ve a persona da empresa; o registro interno guarda quem mandou
const legenda = texto ? ('*Manoel - Suplelive:*\n' + texto) : '';
const rotulos = { image: 'imagem', audio: 'audio', video: 'video' };
const rotulo = '[' + (rotulos[String(b.tipo || '')] || 'arquivo') + ']';

return [{
  json: {
    convNum: num,
    convId: conv,
    msgId: 'la' + ts,
    legenda,
    conv: { id: conv, ultima: (texto || rotulo).slice(0, 120), deUltima: 'agente', ts },
    msg:  { texto: texto || rotulo, de: 'agente', autor: 'Manoel (' + quem + ')', ts },
  },
  binary: {
    arquivo: { data: base64, mimeType: mime, fileName: nome },
  },
}];

// A resposta do Chatwoot traz a mensagem criada, com a URL do anexo ja
// hospedada la. E ela que o LiveOps guarda: assim o balao de quem enviou
// mostra a mesma imagem que o cliente recebeu, e nao uma copia local.
const prep = $('Preparar anexo').first().json;
const r = $json || {};
const brutos = Array.isArray(r.attachments) ? r.attachments : [];
const anexos = brutos.map(a => ({
  tipo: String(a.file_type || 'file'),
  url: String(a.data_url || a.file_url || ''),
  mini: String(a.thumb_url || ''),
  nome: String(a.file_name || ''),
})).filter(a => a.url);

const msgId = r.id ? ('m' + r.id) : prep.msgId;
return [{ json: {
  convId: prep.convId,
  msgId,
  conv: prep.conv,
  msg: Object.assign({}, prep.msg, anexos.length ? { anexos } : {}),
} }];
